const areas=[['All areas','✦','#e7f1fa'],['Heart & circulation','♡','#eaf4fb'],['Diabetes & endocrine','◉','#e4eff8'],['Breathing & sleep','⌁','#edf5fb'],['Neurology & mental health','❋','#e8f2fa'],['Bones, joints & mobility','✣','#eaf2f8'],['Digestive & liver','◉','#e7f1fa'],['Kidney & urinary','⌖','#eaf4fb'],['Cancer care','✳','#e4eff8'],['Surgery & wound care','✚','#edf5fb'],['Infection & testing','⌕','#e8f2fa'],['Eyes, ears & dental','◉','#eaf2f8'],['Children & maternity','♡','#e7f1fa'],['Rehabilitation & assistive','➜','#eaf4fb'],['Self-care & monitoring','⌂','#e4eff8'],['Hospital & pharmacy','▦','#edf5fb']];
const devices=[
{id:'glucometer',name:'Blood glucose meter',icon:'🩸',area:'Diabetes & endocrine',tags:['diabetes','blood sugar','glucose','monitoring','self-care'],color:'#e8f2fa',short:'Checks glucose in a small blood sample to support day-to-day diabetes monitoring.',what:'A handheld meter reads glucose from a drop of blood placed on a compatible test strip. Results can help a person and their care team understand glucose patterns.',use:'Wash and dry hands, insert the matching strip, use the lancing device as instructed, then apply the blood drop. Follow the specific meter manual and care-team plan.',brands:['Accu-Chek (Roche)','OneTouch (LifeScan)','Contour (Ascensia)','FreeStyle (Abbott)'],origin:'Portable electronic meters and enzymatic strip methods evolved from clinical chemistry and home testing technologies; exact design and manufacturing origin varies by brand and model.',setting:'Home / clinic'},
{id:'cgm',name:'Continuous glucose monitor',icon:'◉',area:'Diabetes & endocrine',tags:['diabetes','blood sugar','glucose','wearable','monitoring'],color:'#eaf2f8',short:'A small wearable sensor tracks glucose trends throughout the day and night.',what:'A sensor worn on the skin measures glucose in interstitial fluid at regular intervals and sends readings to a reader or compatible phone.',use:'A sensor is applied and replaced according to its labeling. Users should follow instructions for alerts, sensor changes, skin care, and when a confirmatory finger-stick is needed.',brands:['FreeStyle Libre (Abbott)','Dexcom G7 (Dexcom)','Guardian (Medtronic)'],origin:'Wearable glucose sensing grew from biosensor and electrochemical measurement research. Availability and approved uses differ across markets.',setting:'Home / clinic'},
{id:'bp-monitor',name:'Blood pressure monitor',icon:'⌁',area:'Heart & circulation',tags:['blood pressure','hypertension','heart','monitoring','self-care'],color:'#eaf4fb',short:'Measures blood pressure using an inflatable cuff, usually on the upper arm or wrist.',what:'An automated monitor inflates a cuff and estimates systolic and diastolic pressure and pulse. A series of properly taken readings is more useful than one isolated value.',use:'Sit quietly with back supported and feet flat. Use the correct cuff size on a bare arm at heart level, and follow your clinician’s plan for timing and recording readings.',brands:['Omron','Microlife','A&D Medical','Beurer'],origin:'Modern electronic monitors build on the auscultatory sphygmomanometer and oscillometric measurement methods; manufacturers and production sites vary.',setting:'Home / clinic'},
{id:'pulse-ox',name:'Pulse oximeter',icon:'▣',area:'Breathing & sleep',tags:['breathing','oxygen','lung','respiratory','monitoring'],color:'#e7f1fa',short:'Estimates blood oxygen saturation and pulse through a fingertip sensor.',what:'A fingertip device uses light absorption to estimate peripheral oxygen saturation (SpO₂) and pulse rate. Readings can be affected by movement, circulation, skin temperature, nail products, and other factors.',use:'Warm the hand, sit still, place the sensor as shown in the manual, and wait for a stable reading. Interpret results with symptoms and professional advice, not alone.',brands:['Nonin','Masimo','Beurer','ChoiceMMed'],origin:'Pulse oximetry emerged from optical measurement research and was developed into compact clinical and consumer instruments during the late 20th century.',setting:'Home / clinic'},
{id:'cpap',name:'CPAP / PAP device',icon:'〰',area:'Breathing & sleep',tags:['breathing','sleep apnea','snoring','respiratory','sleep'],color:'#eaf4fb',short:'Delivers prescribed air pressure through a mask to help keep the airway open during sleep.',what:'Positive airway pressure (PAP) systems include fixed-pressure CPAP, auto-adjusting APAP, and bilevel devices. Device type and settings depend on clinical assessment.',use:'Use only with prescribed settings and a fitted mask. Follow cleaning and replacement instructions for tubing, filters, humidifier parts, and mask components.',brands:['ResMed','Philips Respironics','Fisher & Paykel Healthcare','BMC Medical'],origin:'Modern PAP therapy developed from respiratory physiology and sleep medicine; Australian clinician Colin Sullivan described a pioneering CPAP system in 1981.',setting:'Home / sleep clinic'},
{id:'thermometer',name:'Digital thermometer',icon:'🌡️',area:'Self-care & monitoring',tags:['fever','temperature','infection','monitoring','children'],color:'#e4eff8',short:'Measures body temperature using an electronic sensor at an approved site.',what:'Digital thermometers convert sensor measurements into a temperature reading. Oral, axillary, tympanic, and temporal models use different methods and are not interchangeable.',use:'Use the location and technique described in the manual. Clean the device as directed and note the measurement site when sharing results.',brands:['Omron','Braun','Kinsa','Microlife'],origin:'Electronic clinical thermometers replaced many mercury designs using thermistor and infrared sensing technologies.',setting:'Home / clinic'},
{id:'stethoscope',name:'Stethoscope',icon:'♧',area:'Heart & circulation',tags:['heart','breathing','examination','diagnosis','clinic'],color:'#edf5fb',short:'Helps clinicians listen to sounds from the heart, lungs, and other body systems.',what:'A stethoscope transmits body sounds through a chest piece and tubing to the listener. It is an examination aid and does not diagnose a condition by itself.',use:'Clinicians place the chest piece on selected body areas and compare sounds. Proper cleaning between patients is essential.',brands:['3M Littmann','MDF Instruments','ADC','Riester'],origin:'The first stethoscope was invented by French physician René Laennec in 1816; current acoustic and electronic models build on that design.',setting:'Clinic / hospital'},
{id:'ecg',name:'Electrocardiograph (ECG)',icon:'〽',area:'Heart & circulation',tags:['heart','rhythm','cardiac','diagnosis','clinic'],color:'#eaf4fb',short:'Records the heart’s electrical activity through electrodes placed on the skin.',what:'A 12-lead ECG captures electrical signals from multiple directions and displays them as a tracing for qualified interpretation.',use:'Electrodes are placed on the chest and limbs while the person lies still. A trained professional reviews the tracing alongside symptoms and history.',brands:['GE HealthCare','Philips','Nihon Kohden','Schiller'],origin:'The clinical ECG grew from 19th-century electrophysiology, with Willem Einthoven’s string galvanometer enabling practical electrocardiography.',setting:'Clinic / hospital'},
{id:'holter',name:'Holter / ambulatory ECG monitor',icon:'▣',area:'Heart & circulation',tags:['heart','rhythm','palpitations','cardiac','monitoring'],color:'#e8f2fa',short:'Records heart rhythm over an extended period while a person goes about daily activities.',what:'A portable ECG recorder captures heart electrical activity continuously or intermittently to help clinicians investigate symptoms or rhythm patterns.',use:'Wear and care for the monitor as instructed, keep a symptom/activity diary if requested, and return the equipment for analysis.',brands:['Philips','GE HealthCare','Bittium','Spacelabs'],origin:'Ambulatory ECG monitoring became practical as electronics and portable recording media allowed rhythm collection outside hospitals.',setting:'Home / clinic'},
{id:'pacemaker',name:'Implantable pacemaker',icon:'♡',area:'Heart & circulation',tags:['heart','slow heart rate','bradycardia','cardiac','implant'],color:'#eaf4fb',short:'An implanted system that monitors heart rhythm and provides electrical pacing when needed.',what:'A pacemaker includes a pulse generator and one or more leads, or a leadless unit. It is prescribed and implanted by specialist teams for specific rhythm conditions.',use:'Implantation and programming are performed by clinicians. People with pacemakers need follow-up and device-specific guidance about activity and electromagnetic sources.',brands:['Medtronic','Abbott','Boston Scientific','BIOTRONIK'],origin:'Electrical pacing research in the 20th century led to the first implantable pacemakers in the late 1950s; current systems vary greatly by indication and design.',setting:'Hospital / specialist care'},
{id:'aed',name:'Automated external defibrillator',icon:'⚡',area:'Heart & circulation',tags:['heart','cardiac arrest','emergency','defibrillator'],color:'#eaf2f8',short:'Guides a responder through checking for a shockable rhythm and delivering a shock if advised.',what:'An AED analyzes heart rhythm through adhesive pads and prompts the user. It is designed for emergency response alongside CPR and emergency services.',use:'Call emergency services, follow the spoken and visual prompts, and do not touch the person during rhythm analysis or shock delivery.',brands:['ZOLL','Philips HeartStart','LIFEPAK (Stryker)','Defibtech'],origin:'External defibrillation evolved from mid-20th-century cardiac resuscitation research; public-access AEDs added rhythm analysis and voice prompts.',setting:'Public / emergency'},
{id:'insulin-pump',name:'Insulin pump',icon:'▰',area:'Diabetes & endocrine',tags:['diabetes','insulin','blood sugar','endocrine'],color:'#eaf2f8',short:'A wearable or implantable pump delivers programmed insulin under a prescribed care plan.',what:'Insulin pumps deliver rapid-acting insulin through a small infusion set or pod. Some systems communicate with CGMs; automation and compatibility are model-specific.',use:'Requires training, an individualized prescription, and ongoing monitoring. Follow the manufacturer and diabetes team instructions for infusion sites, alarms, and backup plans.',brands:['MiniMed (Medtronic)','Omnipod (Insulet)','Tandem Diabetes Care','YpsoPump (Ypsomed)'],origin:'Portable insulin infusion systems developed as electronics miniaturized; present-day pumps include tubed and patch formats.',setting:'Home / specialist care'},
{id:'inhaler-spacer',name:'Metered-dose inhaler + spacer',icon:'▥',area:'Breathing & sleep',tags:['asthma','breathing','lung','respiratory','inhaler'],color:'#e7f1fa',short:'A handheld inhaler releases a measured medicine dose; a spacer can make coordination easier.',what:'Pressurized metered-dose inhalers deliver aerosolized medicine. A valved holding chamber (spacer) helps hold the aerosol briefly for inhalation.',use:'The technique differs by device and medicine. Follow the device leaflet, receive a demonstration from a health professional, and clean the spacer as directed.',brands:['GSK','AstraZeneca','Chiesi','Cipla'],origin:'Pressurized inhalers were developed in the 1950s, with spacers and holding chambers later added to support medicine delivery technique.',setting:'Home / clinic'},
{id:'nebulizer',name:'Nebulizer',icon:'☁',area:'Breathing & sleep',tags:['breathing','asthma','lung','respiratory','medicine delivery'],color:'#e7f1fa',short:'Turns a compatible liquid medicine into an inhalable mist using a compressor or mesh.',what:'Nebulizers are medicine-delivery devices. The medicine, dose, and suitability must come from a clinician; not every liquid can be nebulized.',use:'Assemble and clean components following the exact manual. Use only medicine intended and prescribed for nebulization.',brands:['PARI','Omron','Philips Respironics','Drive DeVilbiss'],origin:'Nebulization developed from aerosol science; modern compressors and mesh devices make treatment possible in homes and clinics.',setting:'Home / clinic'},
{id:'hearing-aid',name:'Hearing aid',icon:'◖',area:'Eyes, ears & dental',tags:['hearing','hearing loss','audiology','assistive'],color:'#e7f1fa',short:'A wearable electronic device that amplifies and processes sound for an individual.',what:'Hearing aids use microphones, signal processing, and a receiver to make sounds more accessible. They are selected and programmed based on hearing assessment and user needs.',use:'A hearing care professional helps with fitting and adjustment. Keep the device dry and clean as directed and replace or recharge its power source as required.',brands:['Phonak','Signia','Oticon','ReSound','Widex'],origin:'Electronic hearing aids evolved from carbon microphones and vacuum-tube amplifiers to transistor and digital signal-processing systems.',setting:'Home / audiology'},
{id:'wheelchair',name:'Manual wheelchair',icon:'♿',area:'Rehabilitation & assistive',tags:['mobility','disability','rehabilitation','wheelchair','assistive'],color:'#eaf4fb',short:'Provides seated mobility with configuration matched to a person’s posture and daily needs.',what:'Manual wheelchairs may be self-propelled or attendant-propelled. Fit, seating, pressure management, and environment all affect safe, comfortable use.',use:'A rehabilitation professional can help with fit, transfers, propulsion, brakes, and maintenance. Check wheels and brakes regularly.',brands:['Invacare','Sunrise Medical','Permobil','Karma'],origin:'Wheelchairs have a long history; modern folding frames and adjustable seating developed through mobility engineering and rehabilitation practice.',setting:'Home / community'},
{id:'prosthesis',name:'Limb prosthesis',icon:'✣',area:'Rehabilitation & assistive',tags:['amputation','mobility','rehabilitation','orthopedic','assistive'],color:'#eaf4fb',short:'An externally worn device that replaces part or all of a missing limb.',what:'A prosthesis may include a socket, suspension, structural components, and a terminal device or foot. Design depends on anatomy, function, comfort, and goals.',use:'Fitting and training are provided by a prosthetist and rehabilitation team. Skin checks, gradual wear schedules, and maintenance follow individualized advice.',brands:['Ottobock','Össur','Blatchford','Fillauer'],origin:'Prosthetic limbs have ancient origins; modern systems combine materials engineering, biomechanics, and individualized rehabilitation.',setting:'Rehabilitation / home'},
{id:'knee-implant',name:'Knee replacement implant',icon:'✣',area:'Bones, joints & mobility',tags:['knee pain','osteoarthritis','orthopedic','implant','joint'],color:'#eaf4fb',short:'A surgically implanted system that replaces damaged joint surfaces in selected cases.',what:'Knee arthroplasty components are typically metal and polymer parts chosen for a person’s anatomy and clinical situation. Surgery is one option after specialist evaluation.',use:'Implantation is performed by an orthopedic surgical team. Recovery and rehabilitation plans are individualized; device make and model are documented for future care.',brands:['Zimmer Biomet','Stryker','DePuy Synthes','Smith+Nephew','Enovis'],origin:'Modern joint replacement advanced in the 20th century through orthopedic surgery, materials science, and prosthetic design.',setting:'Hospital / rehabilitation'},
{id:'dialysis',name:'Hemodialysis system',icon:'◈',area:'Kidney & urinary',tags:['kidney','renal failure','dialysis','nephrology'],color:'#eaf4fb',short:'Filters waste and extra fluid from blood through a dialyzer in a supervised treatment system.',what:'A hemodialysis machine circulates blood through a dialyzer and returns it to the body. Access type, prescription, and monitoring are managed by a renal care team.',use:'Treatment is delivered by trained staff or through a prescribed home program with extensive training. Follow infection-control and access-care instructions.',brands:['Fresenius Medical Care','Baxter','Nipro','B. Braun'],origin:'Dialysis technology grew from 20th-century membrane science and extracorporeal circulation research.',setting:'Dialysis center / home'},
{id:'urinary-catheter',name:'Urinary catheter',icon:'⌁',area:'Kidney & urinary',tags:['urinary','bladder','urology','catheter','incontinence'],color:'#eaf4fb',short:'A flexible tube used to drain urine from the bladder when clinically indicated.',what:'Catheters include intermittent, indwelling, and external types. Selection depends on the reason for use and individual circumstances.',use:'Insertion, maintenance, and removal should follow clinician instruction and product labeling. Catheter use carries risks including infection and should be reviewed regularly.',brands:['Coloplast','Hollister','Bard (BD)','Teleflex'],origin:'Catheter designs developed over centuries from simple drainage tubes into specialized materials and formats.',setting:'Home / hospital'},
{id:'endoscope',name:'Flexible endoscope',icon:'◎',area:'Digestive & liver',tags:['digestive','stomach','colon','endoscopy','diagnosis'],color:'#e7f1fa',short:'A camera-equipped flexible instrument lets clinicians examine internal passages and organs.',what:'Endoscopes transmit an image from a lighted tip and can accommodate instruments for sampling or treatment. Different scopes serve different specialties.',use:'Performed by trained clinicians in a clinical setting, with preparation, sedation, cleaning, and reprocessing protocols appropriate to the procedure.',brands:['Olympus','Fujifilm','PENTAX Medical','KARL STORZ'],origin:'Endoscopy progressed from rigid optical instruments to flexible fiber-optic and video systems during the 20th century.',setting:'Hospital / clinic'},
{id:'syringe',name:'Syringe & needle',icon:'╱',area:'Hospital & pharmacy',tags:['injection','medicine delivery','hospital','pharmacy'],color:'#e4eff8',short:'A graduated barrel and plunger draw up or deliver measured fluid through a compatible tip or needle.',what:'Syringes are available in many volumes and designs for different clinical tasks. Insulin, oral, irrigation, and injection syringes are not interchangeable.',use:'Use the right syringe for the intended purpose, follow training and labeling, and dispose of sharps in an approved sharps container.',brands:['BD','Terumo','Nipro','Vygon'],origin:'Syringe-like instruments date back centuries; modern hypodermic syringes emerged alongside 19th-century injection techniques.',setting:'Home / clinic / hospital'},
{id:'iv-pump',name:'Infusion pump',icon:'▤',area:'Hospital & pharmacy',tags:['infusion','medicine delivery','hospital','pump'],color:'#e4eff8',short:'Controls the rate and volume of fluid or medicine delivered through an infusion line.',what:'Volumetric, syringe, and ambulatory pumps are designed for different uses. Drug libraries, alarms, and safety features depend on model and setting.',use:'Set-up and programming require trained users and the specific instructions for use. Patients should not change settings unless directed by their care team.',brands:['Baxter','BD Alaris','ICU Medical','B. Braun','Fresenius Kabi'],origin:'Electronic infusion control evolved to improve accuracy over gravity-fed delivery; modern pumps include alarms and software safeguards.',setting:'Hospital / specialist home care'},
{id:'xray',name:'X-ray imaging system',icon:'▧',area:'Surgery & wound care',tags:['imaging','fracture','bones','diagnosis','radiology'],color:'#edf5fb',short:'Uses a controlled X-ray beam and detector to create images of internal structures.',what:'Radiography is commonly used to assess bones and other structures. The ordering clinician considers the question, potential benefits, and radiation exposure.',use:'Imaging is performed by trained staff using positioning and protection protocols. Pregnancy status and prior imaging may be relevant to discuss.',brands:['GE HealthCare','Siemens Healthineers','Philips','Canon Medical'],origin:'X-rays were discovered by Wilhelm Conrad Röntgen in 1895; digital detectors and image processing are now widely used.',setting:'Imaging center / hospital'},
{id:'ultrasound',name:'Ultrasound system',icon:'◌',area:'Children & maternity',tags:['imaging','pregnancy','maternity','heart','diagnosis'],color:'#e7f1fa',short:'Uses high-frequency sound waves to produce real-time images without ionizing radiation.',what:'A transducer sends and receives sound waves. Ultrasound is used across obstetrics, cardiology, abdominal imaging, and many other areas.',use:'A trained professional selects the probe and settings for the clinical question. Non-medical “keepsake” scans are different from diagnostic examinations.',brands:['GE HealthCare','Philips','Siemens Healthineers','Canon Medical','Mindray'],origin:'Diagnostic ultrasound developed from sonar and acoustic research in the mid-20th century.',setting:'Clinic / hospital'},
{id:'mri',name:'MRI scanner',icon:'◉',area:'Neurology & mental health',tags:['imaging','brain','spine','diagnosis','radiology'],color:'#e8f2fa',short:'Uses a strong magnetic field and radio waves to create detailed images of body tissues.',what:'Magnetic resonance imaging does not use ionizing radiation. The scanner and protocol are selected according to the body area and clinical question.',use:'Before scanning, staff screen for implants, metal, and other safety considerations. Patients need to follow the MRI team’s instructions throughout.',brands:['Siemens Healthineers','GE HealthCare','Philips','Canon Medical'],origin:'MRI emerged from nuclear magnetic resonance research and medical imaging advances in the 1970s.',setting:'Imaging center / hospital'},
{id:'neurostim',name:'Deep brain stimulation system',icon:'✳',area:'Neurology & mental health',tags:['parkinson','tremor','neurology','movement','implant'],color:'#e8f2fa',short:'An implanted system delivers electrical stimulation to selected brain targets for specific movement disorders.',what:'DBS systems include implanted leads and a pulse generator. They may be considered for selected people after specialist evaluation; it is not suitable for every condition or person.',use:'Implantation and programming are specialist procedures. Ongoing follow-up adjusts settings and manages the system.',brands:['Medtronic','Abbott','Boston Scientific'],origin:'DBS for movement disorders developed from functional neurosurgery and neurophysiology research in the late 20th century.',setting:'Hospital / specialist care'},
{id:'wound-dressing',name:'Advanced wound dressing',icon:'▧',area:'Surgery & wound care',tags:['wound','burn','surgery','skin','dressing'],color:'#edf5fb',short:'A broad family of dressings designed to manage moisture, protect tissue, or support wound care.',what:'Foams, alginates, hydrocolloids, films, and antimicrobial dressings have different properties and uses. The wound and dressing plan should be assessed by a qualified professional.',use:'Use the dressing and change schedule recommended for the wound. Seek professional guidance for worsening pain, spreading redness, fever, or other concerns.',brands:['Mölnlycke','Smith+Nephew','3M','ConvaTec','Coloplast'],origin:'Modern wound dressings build on advances in biomaterials and moisture-balanced healing approaches.',setting:'Home / clinic / hospital'},
{id:'pregnancy-test',name:'Home pregnancy test',icon:'＋',area:'Children & maternity',tags:['pregnancy','testing','self-test','maternity'],color:'#e7f1fa',short:'Detects human chorionic gonadotropin (hCG) in urine as an aid to pregnancy testing.',what:'Most home tests use antibodies that react to hCG. Timing, test sensitivity, and correct use affect results; a test does not assess pregnancy health or location.',use:'Follow the specific package instructions and read results within the stated time window. Contact a healthcare professional with questions or urgent symptoms.',brands:['Clearblue','First Response','Prega News','Pee Safe'],origin:'Home pregnancy tests brought immunoassay technology into consumer self-testing and became widely available in the late 20th century.',setting:'Home / pharmacy'},
{id:'ivd-analyzer',name:'Clinical laboratory analyzer',icon:'▦',area:'Infection & testing',tags:['lab','blood test','infection','diagnosis','pathology'],color:'#e8f2fa',short:'Automates measurements on blood, urine, or other samples in a clinical laboratory.',what:'Analyzers cover chemistry, hematology, immunoassay, microbiology, and other tests. Their results depend on validated methods, sample quality, and trained interpretation.',use:'Laboratory staff operate the instrument under quality-control and biosafety procedures. Patients generally interact through specimen collection rather than device operation.',brands:['Roche Diagnostics','Abbott','Siemens Healthineers','Beckman Coulter','Sysmex'],origin:'Modern analyzers combine laboratory assay chemistry, optics, fluidics, and automation.',setting:'Laboratory / hospital'},
{id:'colonoscope',name:'Colonoscope',icon:'◎',area:'Digestive & liver',tags:['colon','digestive','screening','endoscopy','colorectal'],color:'#e7f1fa',short:'A flexible camera instrument used by clinicians to examine the colon and rectum.',what:'Colonoscopy can support screening, diagnosis, and selected interventions. The procedure and timing depend on individual risk and clinical guidance.',use:'Requires bowel preparation and a trained clinical team. Follow the care team’s instructions before and after the procedure.',brands:['Olympus','Fujifilm','PENTAX Medical'],origin:'Flexible endoscopy evolved through fiber-optic and video imaging technologies in the 20th century.',setting:'Hospital / endoscopy clinic'},
{id:'hemodialysis-access',name:'Vascular access for dialysis',icon:'⌁',area:'Kidney & urinary',tags:['kidney','dialysis','vascular access','nephrology'],color:'#eaf4fb',short:'A fistula, graft, or catheter provides access to blood for hemodialysis treatment.',what:'Different access types have different benefits and risks. Planning and care are coordinated by a renal and vascular team.',use:'Patients receive access-specific instructions for checks and care. Report changes such as pain, redness, swelling, or reduced function to the care team.',brands:['Access type is selected clinically'],origin:'Dialysis access evolved alongside chronic hemodialysis, vascular surgery, and biomaterials.',setting:'Hospital / dialysis center'},
{id:'surgical-robot',name:'Robotic-assisted surgical system',icon:'⚙',area:'Surgery & wound care',tags:['surgery','robotics','operation','hospital'],color:'#edf5fb',short:'A surgeon-controlled platform translates hand movements into precise instrument motion.',what:'Robotic-assisted systems provide visualization and instrument control for selected procedures. The system does not operate autonomously; a trained surgeon remains in control.',use:'Used by trained surgical teams in an operating room. Whether a robotic approach is appropriate depends on the procedure, clinician, and patient.',brands:['da Vinci (Intuitive)','Hugo (Medtronic)','Versius (CMR Surgical)'],origin:'Surgical robotics developed from computer-assisted surgery and minimally invasive instrumentation research.',setting:'Operating room'},
{id:'mammography',name:'Mammography system',icon:'▤',area:'Cancer care',tags:['breast','cancer','screening','imaging'],color:'#e4eff8',short:'A specialized X-ray system creates breast images for screening or diagnostic evaluation.',what:'Mammography uses low-dose X-rays and compression to create images. Screening schedules and diagnostic follow-up depend on local guidelines and individual context.',use:'Performed by trained imaging staff. Share relevant history, implants, and symptoms with the care team and follow preparation guidance.',brands:['Hologic','GE HealthCare','Siemens Healthineers','Fujifilm'],origin:'Dedicated breast imaging evolved from conventional radiography, with modern digital detectors and tomosynthesis options.',setting:'Imaging center / hospital'},
{id:'bone-densitometer',name:'Bone densitometer (DXA)',icon:'▥',area:'Bones, joints & mobility',tags:['bone','osteoporosis','fracture risk','imaging'],color:'#eaf4fb',short:'Measures bone mineral density, commonly at the hip and spine, using low-dose X-rays.',what:'DXA is one tool clinicians use to assess bone density and fracture risk alongside other risk factors.',use:'A trained operator positions the person for the scan and a qualified clinician interprets the result in context.',brands:['Hologic','GE HealthCare','OsteoSys'],origin:'Dual-energy X-ray absorptiometry grew from bone mineral measurement research and became a widely used densitometry method.',setting:'Imaging center / clinic'},
{id:'nebulizer-spacer',name:'Peak flow meter',icon:'↗',area:'Breathing & sleep',tags:['asthma','breathing','lung','monitoring'],color:'#e7f1fa',short:'Measures how quickly a person can exhale, sometimes as part of an asthma action plan.',what:'Peak expiratory flow meters measure peak flow and may help track changes over time for some people with asthma.',use:'Use the technique and recording plan taught by a clinician. A single number should be interpreted using an individual action plan.',brands:['Philips','Clement Clarke','Vitalograph'],origin:'Peak flow measurement developed as a portable method to quantify expiratory airflow in respiratory care.',setting:'Home / clinic'},
{id:'neuro-wheel',name:'Cochlear implant system',icon:'◖',area:'Eyes, ears & dental',tags:['hearing','deafness','cochlear','implant','assistive'],color:'#e7f1fa',short:'An implanted electronic system stimulates the auditory nerve for some people with severe hearing loss.',what:'A cochlear implant has an internal receiver and electrode array plus an external sound processor. Assessment, surgery, and rehabilitation are part of the care pathway.',use:'Implantation and mapping are handled by specialist teams. The external processor requires daily care and maintenance.',brands:['Cochlear','Advanced Bionics','MED-EL'],origin:'Cochlear implant development combined auditory neuroscience, electronics, and surgical innovation from the mid-20th century onward.',setting:'Specialist clinic / home'}
];
const addDevice=(id,name,area,tags,short,what,use,brands,setting)=>({id,name,icon:'▧',area,tags,color:'#eaf4fb',short,what,use,brands,origin:'This category includes multiple technologies and manufacturing origins; exact specifications and availability vary by model and market.',setting});
const additionalDevices=[
  addDevice('ct-scanner','CT scanner','Surgery & wound care',['imaging','radiology','computed tomography','diagnosis'],'Uses X-rays and computer reconstruction to create cross-sectional images.','A CT scanner rotates an X-ray source and detector around the body to produce detailed image slices or 3D reconstructions.','The radiology team screens for safety, positions the patient, and may use contrast when prescribed; a qualified clinician interprets the images.',['GE HealthCare','Siemens Healthineers','Philips','Canon Medical'],'Imaging center / hospital'),
  addDevice('dental-opg','Panoramic dental X-ray (OPG)','Eyes, ears & dental',['dental','x-ray','imaging','teeth','diagnosis'],'Captures a panoramic image of the teeth, jaws, and surrounding structures.','An orthopantomogram system rotates around the head to create a broad dental image in one exposure.','Dental imaging staff position the patient and ask them to remain still while the unit moves around the head.',['Vatech','Planmeca','Carestream Dental','Dentsply Sirona'],'Dental clinic / imaging center'),
  addDevice('echocardiography','Echocardiography system','Heart & circulation',['heart','echo','ultrasound','cardiac imaging','diagnosis'],'Uses ultrasound to create moving images of the heart.','An echocardiography system combines ultrasound imaging and Doppler measurements to assess cardiac structures and blood flow.','A sonographer or clinician applies gel and moves a probe over the chest; specialized studies use other approaches.',['GE HealthCare','Philips','Siemens Healthineers','Canon Medical'],'Clinic / hospital'),
  addDevice('eeg','Electroencephalograph (EEG)','Neurology & mental health',['brain','electrical activity','neurology','seizure','diagnosis'],'Records electrical activity from the brain through scalp electrodes.','An EEG system amplifies and records signals detected by electrodes placed on the scalp.','A trained technologist applies electrodes and records activity under the clinician’s requested protocol.',['Nihon Kohden','Natus','Cadwell','Compumedics'],'Neurology clinic / hospital'),
  addDevice('emg-ncv','EMG and nerve-conduction system','Neurology & mental health',['nerve','muscle','neurology','EMG','NCV','diagnosis'],'Measures electrical activity in muscles and signals along peripheral nerves.','Electromyography and nerve-conduction equipment records responses using surface electrodes and, for some tests, needle electrodes.','A qualified clinician or technologist performs the test and interprets results in clinical context.',['Natus','Cadwell','Nihon Kohden','Neurosoft'],'Neurodiagnostic clinic / hospital'),
  addDevice('audiometer','Audiometer','Eyes, ears & dental',['hearing','audiology','hearing test','diagnosis'],'Presents controlled sounds to assess hearing thresholds.','An audiometer delivers calibrated tones or speech through headphones or a sound booth setup.','An audiologist guides the test and records responses at different sound levels and frequencies.',['Interacoustics','MAICO','Amplivox','Grason-Stadler'],'Audiology clinic'),
  addDevice('otoscope','Otoscope','Eyes, ears & dental',['ear','ENT','examination','diagnosis'],'Provides magnified illumination to examine the outer ear and eardrum.','A handheld otoscope uses a light and viewing lens or camera with a compatible speculum.','A trained user selects a clean, appropriate speculum and examines the ear without forcing the instrument.',['Welch Allyn','HEINE','Riester','KaWe'],'Clinic / audiology'),
  addDevice('ophthalmoscope','Ophthalmoscope','Eyes, ears & dental',['eye','ophthalmology','retina','examination'],'Illuminates and magnifies internal structures of the eye.','Direct and indirect ophthalmoscopes help clinicians view the fundus and optic nerve.','An eye-care professional selects the instrument and technique appropriate to the examination.',['Welch Allyn','HEINE','Keeler','Riester'],'Eye clinic'),
  addDevice('fetal-doppler','Fetal Doppler monitor','Children & maternity',['pregnancy','fetal heart','obstetrics','monitoring'],'Uses ultrasound Doppler to detect fetal heart activity during clinical assessment.','A handheld Doppler converts reflected ultrasound signals into an audible signal or displayed rate.','Used by trained maternity staff according to clinical protocol; a home reading cannot confirm fetal wellbeing.',['Huntleigh','Edan','Bistos','Philips'],'Maternity clinic / hospital'),
  addDevice('fetal-monitor','Fetal and maternal monitor (CTG)','Children & maternity',['pregnancy','labor','fetal heart','contraction','monitoring'],'Records fetal heart rate and uterine activity during selected maternity care.','A cardiotocography monitor displays fetal heart-rate and contraction traces from sensors placed on the abdomen.','Maternity staff position sensors, check signal quality, and interpret the trace alongside the clinical picture.',['Philips','GE HealthCare','Edan','Bistos'],'Maternity unit / hospital'),
  addDevice('spirometer','Spirometer','Breathing & sleep',['lung','breathing','pulmonary function','PFT','diagnosis'],'Measures inhaled and exhaled airflow and volumes during lung-function testing.','A spirometer records airflow and volume during coached breathing maneuvers and produces measurements for clinical review.','A trained tester explains and supervises the maneuvers using the device’s infection-control and calibration procedures.',['Vitalograph','MIR','Schiller','ndd'],'Pulmonary clinic / hospital'),
  addDevice('cardiac-stress-test','Cardiac stress-test system (TMT)','Heart & circulation',['heart','exercise test','TMT','ECG','diagnosis'],'Records ECG and related measurements during supervised exercise testing.','A treadmill or cycle ergometer is combined with ECG and monitoring equipment to record responses to exertion.','A clinical team supervises the test, monitors symptoms and vital signs, and follows the prescribed stopping protocol.',['GE HealthCare','Philips','Schiller','BPL Medical'],'Cardiology clinic / hospital'),
  addDevice('uroflowmeter','Uroflowmetry system','Kidney & urinary',['urinary','bladder','urology','flow measurement','diagnosis'],'Measures urine-flow rate and volume during a voiding test.','A uroflowmeter collects flow measurements over time and may pair with a scale or recording software.','The clinic explains the test and reviews the recorded flow pattern with other findings.',['Laborie','Mediwatch','MMS','Dantec'],'Urology clinic'),
  addDevice('body-composition-monitor','Body-composition analyzer','Self-care & monitoring',['body composition','weight','fitness','monitoring'],'Estimates body composition using a method such as bioelectrical impedance.','These analyzers may report weight and estimates such as body-fat or lean-mass measures; methods and accuracy vary.','Follow the model’s measurement conditions and treat results as estimates, not a diagnosis.',['InBody','Tanita','seca','Omron'],'Clinic / fitness / home'),
  addDevice('colposcope','Colposcope','Children & maternity',['gynecology','cervix','examination','diagnosis'],'Magnifies and illuminates the cervix and nearby tissue for examination.','A colposcope is an optical examination instrument used by trained clinicians during a gynecologic assessment.','The clinician positions the instrument outside the body and conducts the examination in a clinical setting.',['Leisegang','Zeiss','MedGyn','Olympus'],'Gynecology clinic'),
  addDevice('anesthesia-workstation','Anesthesia workstation','Surgery & wound care',['anesthesia','operating room','ventilation','monitoring'],'Combines anesthesia gas delivery, breathing circuits, and ventilation controls.','An anesthesia workstation supports delivery and monitoring of anesthetic gases and ventilation during procedures.','Configured and operated only by trained anesthesia professionals using the exact model instructions and facility checks.',['Dräger','GE HealthCare','Mindray','Penlon'],'Operating room'),
  addDevice('ventilator','Mechanical ventilator','Breathing & sleep',['respiratory','ventilation','critical care','breathing support'],'Supports or controls breathing for patients who need assisted ventilation.','A ventilator moves gas through a breathing circuit using settings selected for a specific clinical situation.','Trained respiratory and medical staff select settings, monitor the patient, and respond to alarms.',['Dräger','Hamilton Medical','Getinge','Mindray'],'ICU / hospital'),
  addDevice('oxygen-concentrator','Oxygen concentrator','Breathing & sleep',['oxygen','respiratory','home care','oxygen therapy'],'Separates oxygen from room air to provide a concentrated oxygen supply.','A concentrator uses filtration and compression to produce oxygen-enriched gas for a prescribed therapy plan.','Use only at the prescribed flow and with the supplied accessories; keep the unit ventilated and follow safety instructions.',['Philips Respironics','Nidek Medical','Yuwell','Inogen'],'Home / clinic'),
  addDevice('suction-machine','Medical suction unit','Hospital & pharmacy',['suction','airway','surgery','fluid removal'],'Creates controlled negative pressure to remove fluids from a clinical field or airway.','Portable and wall-connected suction systems use a pump, collection container, tubing, and filters.','Setup and use depend on the clinical purpose; trained staff follow the device instructions and infection-control procedure.',['Medela','Laerdal','Allied Healthcare','SSCOR'],'Clinic / hospital'),
  addDevice('electrosurgical-unit','Electrosurgical unit (cautery)','Surgery & wound care',['surgery','electrosurgery','operating room','tissue'],'Uses high-frequency electrical energy for cutting or coagulation during procedures.','An electrosurgical generator works with compatible active and return electrodes and accessories.','For trained surgical professionals only; setup, patient contact, and safety checks follow the exact instructions for use.',['Erbe','Medtronic','Bovie','Olympus'],'Operating room'),
  addDevice('syringe-pump','Syringe infusion pump','Hospital & pharmacy',['infusion','medicine delivery','syringe pump','hospital'],'Delivers fluid from a syringe at a controlled rate.','A syringe pump advances a compatible syringe using a motorized mechanism and alarms for selected conditions.','Trained clinical users verify the medication order, syringe, line, and pump settings; patients should not change settings unless directed.',['BD Alaris','B. Braun','Fresenius Kabi','Mindray'],'Hospital / specialist care'),
  addDevice('heart-lung-machine','Heart-lung machine','Heart & circulation',['cardiac surgery','perfusion','heart lung bypass','surgery'],'Temporarily supports circulation and gas exchange during selected heart operations.','A cardiopulmonary bypass system circulates and oxygenates blood while the surgical team performs a procedure.','Operated by specialist perfusion and surgical teams under strict clinical protocols.',['Getinge','LivaNova','Terumo','Medtronic'],'Cardiac operating room'),
  addDevice('iabp','Intra-aortic balloon pump (IABP)','Heart & circulation',['heart','cardiac support','circulation','critical care'],'Provides temporary mechanical circulatory support in selected cardiac situations.','An IABP console synchronizes inflation and deflation of an intra-aortic balloon with the cardiac cycle.','Placed, configured, and monitored by specialist clinical teams; it is not a patient-operated device.',['Getinge','Teleflex','Maquet','Datascope'],'ICU / cardiac care'),
  addDevice('laryngoscope','Laryngoscope','Breathing & sleep',['airway','anesthesia','intubation','emergency'],'Provides a view of the larynx during airway examination or intubation.','Direct and video laryngoscopes use a handle and blade or camera display to support airway visualization.','For trained clinicians only, using the appropriate model, blade, and airway-management protocol.',['HEINE','Welch Allyn','KARL STORZ','Medtronic'],'Emergency / operating room'),
  addDevice('operating-microscope','Operating microscope','Surgery & wound care',['surgery','microscope','magnification','operating room'],'Provides magnified, illuminated views during delicate surgical procedures.','A surgical microscope uses adjustable optics, lighting, and positioning arms to support precise visualization.','Positioned and used by trained surgical teams; specialty and accessories determine configuration.',['ZEISS','Leica Microsystems','Haag-Streit','Olympus'],'Operating room'),
  addDevice('surgical-light','Operating-theatre light','Surgery & wound care',['surgery','lighting','operating room','illumination'],'Provides adjustable, shadow-reduced illumination over the surgical field.','Surgical lights may be ceiling-mounted or mobile and use focused LED or other light sources.','Positioned by trained staff and maintained according to the facility’s cleaning and equipment checks.',['Maquet','STERIS','Stryker','Mindray'],'Operating room'),
  addDevice('laparoscopic-system','Laparoscopic imaging system','Digestive & liver',['laparoscopy','endoscopy','surgery','camera'],'Displays images from a laparoscope during minimally invasive surgery.','A video stack typically combines a camera control unit, light source, display, and compatible scope.','Used by trained operating-room teams; scope handling, setup, and reprocessing are model-specific.',['Olympus','KARL STORZ','Stryker','Richard Wolf'],'Operating room'),
  addDevice('autoclave','Steam sterilizer (autoclave)','Hospital & pharmacy',['sterilization','infection prevention','steam','hospital'],'Uses controlled steam cycles to sterilize compatible reusable instruments.','An autoclave controls temperature, pressure, and exposure time for a validated load and cycle.','Trained sterilization staff follow the instrument, packaging, load, and cycle instructions and verify cycle records.',['STERIS','Getinge','Tuttnauer','Midmark'],'Sterile services / hospital'),
  addDevice('centrifuge','Laboratory centrifuge','Infection & testing',['laboratory','pathology','sample preparation','diagnostic'],'Separates sample components by spinning tubes at controlled speed.','Clinical and research centrifuges use a rotor and programmed speed/time settings for specified sample containers.','Laboratory staff balance loads and use the rotor, tube, and safety instructions for the exact instrument.',['Eppendorf','Thermo Fisher Scientific','Hettich','Remi'],'Laboratory'),
  addDevice('hematology-analyzer','Hematology analyzer (cell counter)','Infection & testing',['blood test','laboratory','cell counter','CBC','diagnostic'],'Counts and classifies blood cells in a laboratory sample.','Automated hematology analyzers use optical, electrical, or other measurement methods to generate blood-count parameters.','Authorized laboratory staff run samples and quality controls and review instrument flags before reporting results.',['Sysmex','Beckman Coulter','Mindray','Abbott'],'Laboratory'),
  addDevice('microtome','Microtome','Infection & testing',['pathology','histology','tissue sectioning','laboratory'],'Cuts thin tissue sections for microscopic examination.','Manual or motorized microtomes hold a specimen block and advance it across a blade at controlled thickness.','Used by trained histology staff with blade guards and laboratory safety procedures.',['Leica Biosystems','Thermo Fisher Scientific','Sakura','SLEE'],'Pathology laboratory'),
  addDevice('radiant-warmer','Radiant infant warmer','Children & maternity',['newborn','neonatal','temperature','maternity'],'Provides controlled radiant heat to help maintain an infant’s temperature in clinical care.','An infant warmer uses an overhead heating element and temperature monitoring features in an open care area.','Configured and monitored by neonatal staff; alarm limits and probes follow unit protocol and model labeling.',['GE HealthCare','Dräger','Atom Medical','Phoenix Medical'],'Neonatal unit'),
  addDevice('neonatal-incubator','Neonatal incubator','Children & maternity',['newborn','neonatal','incubator','temperature'],'Creates a controlled environment for the care of selected newborns.','An incubator regulates warmth and may manage humidity and access while allowing clinical observation and care.','Operated and monitored by neonatal professionals using patient-specific settings and infection-control procedures.',['GE HealthCare','Dräger','Atom Medical','Natus'],'Neonatal unit'),
  addDevice('neonatal-phototherapy','Neonatal phototherapy unit','Children & maternity',['newborn','jaundice','phototherapy','maternity'],'Provides measured light exposure used in clinical management of neonatal jaundice.','Phototherapy units use specified light sources and positioning to deliver treatment under clinical monitoring.','Treatment duration, eye protection, distance, and monitoring are determined by the neonatal team and device instructions.',['Natus','Dräger','GE HealthCare','Atom Medical'],'Neonatal unit'),
  addDevice('tens-unit','TENS unit','Bones, joints & mobility',['pain','electrotherapy','rehabilitation','TENS'],'Delivers low-voltage electrical pulses through skin electrodes for pain-management programs.','A TENS device sends adjustable pulses through electrode pads; suitability and settings differ between people and conditions.','Use only after checking the product instructions and clinician advice, especially when implanted electronics or other cautions apply.',['Omron','Chattanooga','DJO','ITO'],'Home / physiotherapy'),
  addDevice('therapeutic-ultrasound','Therapeutic ultrasound unit','Bones, joints & mobility',['physiotherapy','rehabilitation','ultrasound therapy','treatment'],'Delivers therapeutic ultrasound energy through an applicator used by a clinician.','Physiotherapy units generate ultrasound at selected settings and use a coupling medium at the treatment site.','Applied by a trained therapist according to the clinical plan and device instructions.',['Chattanooga','BTL','Enraf-Nonius','ITO'],'Physiotherapy clinic'),
  addDevice('diathermy-unit','Physiotherapy diathermy unit','Bones, joints & mobility',['physiotherapy','diathermy','electrotherapy','rehabilitation'],'Delivers therapeutic electromagnetic energy in supervised physiotherapy.','Shortwave and microwave diathermy systems use applicators to deliver energy under controlled clinical conditions.','For trained practitioners; patient screening, applicator placement, and safety limits are essential.',['BTL','Chattanooga','Enraf-Nonius','Gymna'],'Physiotherapy clinic'),
  addDevice('traction-system','Traction system','Bones, joints & mobility',['orthopedic','rehabilitation','traction','physiotherapy'],'Applies controlled pulling force as part of selected musculoskeletal care plans.','Traction systems may use a table, harness, and mechanical or motorized force controls.','Used only when prescribed and supervised by a rehabilitation professional; settings and fit are individualized.',['Chattanooga','Enraf-Nonius','BTL','Hill Laboratories'],'Physiotherapy clinic'),
  addDevice('pneumatic-compression','Intermittent pneumatic compression device','Bones, joints & mobility',['circulation','compression','rehabilitation','vascular'],'Inflates and deflates sleeves around a limb according to a programmed cycle.','The pump and sleeves apply intermittent pressure for selected clinical or mobility-support purposes.','Use only with the prescribed sleeve and plan; staff should check fit and contraindications for the specific patient.',['DJO','Arjo','Cardinal Health Kendall','Tactile Medical'],'Hospital / home by prescription'),
  addDevice('patient-lift','Patient lift / hoist','Rehabilitation & assistive',['mobility','transfer','caregiver','patient lift'],'Supports assisted transfers between a bed, chair, or other surface.','Mobile and ceiling lifts use a motorized mechanism and compatible sling to transfer a person with reduced manual lifting.','Caregivers require training in the exact lift, sling, patient assessment, and transfer procedure.',['Arjo','Invacare','Joerns','Prism Medical'],'Hospital / home care'),
  addDevice('walker','Walking frame / walker','Rehabilitation & assistive',['mobility','walking aid','rehabilitation','assistive'],'Provides a stable handhold to support walking and balance.','Walkers include fixed, folding, wheeled, and rollator designs selected for a person’s mobility needs.','A rehabilitation professional can adjust height and teach safe use for the selected frame and environment.',['Invacare','Sunrise Medical','Drive DeVilbiss','Karma'],'Home / community'),
  addDevice('hospital-bed','Adjustable hospital bed','Hospital & pharmacy',['hospital','patient care','positioning','bed'],'Adjusts patient position to support care, comfort, and transfers.','Hospital beds may include powered height, backrest, and leg adjustments plus safety rails and accessories.','Staff or trained caregivers use controls and safety features according to the bed model and care plan.',['Hillrom','Stryker','Arjo','Paramount Bed'],'Hospital / home care'),
  addDevice('stretcher','Patient transport stretcher','Hospital & pharmacy',['transport','emergency','hospital','patient transfer'],'Supports movement of a patient between care areas.','Stretchers vary from ambulance cots to height-adjustable hospital transfer trolleys.','Trained staff secure the patient and use brakes, rails, and transfer mechanisms according to the model.',['Stryker','Ferno','Hillrom','Paramount Bed'],'Hospital / emergency'),
  addDevice('dental-chair','Dental treatment chair','Eyes, ears & dental',['dental','clinic','positioning','oral health'],'Positions a patient for dental examinations and procedures.','A dental chair may provide powered height and backrest movement with an integrated delivery unit.','Dental staff position the chair and use controls and accessories according to the manufacturer’s instructions.',['A-dec','Planmeca','Dentsply Sirona','Belmont'],'Dental clinic'),
  addDevice('dental-handpiece','Dental handpiece / drill','Eyes, ears & dental',['dental','drill','oral health','instrument'],'Rotates a bur or tool for specific dental procedures.','High- and low-speed handpieces connect to a dental unit and use compatible burs and cleaning processes.','Used by dental professionals with the correct bur, protective equipment, and validated reprocessing.',['KaVo','NSK','W&H','Bien-Air'],'Dental clinic'),
  addDevice('dental-implant','Dental implant system','Eyes, ears & dental',['dental','implant','prosthodontics','oral surgery'],'Provides an implanted support for a dental restoration in selected cases.','A dental implant typically includes a fixture placed in bone and compatible abutment and restoration components.','Assessment, placement, and restoration are performed by qualified dental professionals; systems are not interchangeable.',['Straumann','Nobel Biocare','Dentsply Sirona','Osstem'],'Dental clinic / hospital'),
  addDevice('prosthetic-heart-valve','Prosthetic heart valve','Heart & circulation',['heart','valve','cardiac surgery','implant'],'Replaces or supports a diseased heart valve through an implanted prosthesis.','Surgical and transcatheter valve systems differ in material, placement approach, and clinical indication.','Selected and implanted by a specialist heart team; patients need device-specific follow-up.',['Edwards Lifesciences','Medtronic','Abbott','Boston Scientific'],'Cardiac hospital / specialist care'),
  addDevice('vascular-stent','Vascular stent','Heart & circulation',['vascular','stent','cardiology','implant'],'A small expandable scaffold used to support a selected blood vessel.','Stents vary by vessel, material, coating, and delivery system; coronary and peripheral systems are not interchangeable.','Placed by trained specialists during an image-guided procedure; follow-up and medicines are determined by the care team.',['Abbott','Medtronic','Boston Scientific','Terumo'],'Cath lab / hospital'),
  addDevice('angioplasty-balloon','Angioplasty balloon catheter','Heart & circulation',['vascular','angioplasty','catheter','cardiology'],'A catheter-mounted balloon temporarily expands a selected narrowed vessel segment.','Balloon catheters differ by vessel size, length, pressure rating, and intended procedural use.','Chosen and operated by trained interventional clinicians using imaging and the product’s instructions.',['Abbott','Medtronic','Boston Scientific','Terumo'],'Cath lab / hospital'),
  addDevice('breast-pump','Breast pump','Children & maternity',['maternity','breastfeeding','milk expression','home care'],'Expresses breast milk using manual or powered suction.','Breast pumps include manual, single electric, and double electric designs with breast shields and collection kits.','Select a correctly fitted flange and clean parts as directed; seek lactation support if use is painful or difficult.',['Medela','Philips Avent','Spectra','Lansinoh'],'Home / maternity clinic'),
  addDevice('slit-lamp','Slit-lamp biomicroscope','Eyes, ears & dental',['eye','ophthalmology','optometry','examination'],'Uses a focused slit of light and magnification to examine the eye.','An eye-clinic slit lamp combines a microscope, illumination system, and patient support.','An eye-care professional positions the patient and adjusts illumination and magnification during examination.',['Haag-Streit','ZEISS','Topcon','Reichert'],'Eye clinic'),
  addDevice('medical-gas-system','Central medical-gas supply system','Hospital & pharmacy',['medical gas','oxygen','hospital infrastructure','critical care'],'Supplies medical gases through a facility distribution network.','A central system may include source equipment, manifolds, pipelines, alarms, and point-of-use outlets.','Designed, maintained, and checked by qualified biomedical and facilities teams under applicable standards.',['Dräger','BeaconMedaes','Amico','Ohio Medical'],'Hospital infrastructure'),
  addDevice('blood-bank-refrigerator','Blood-bank refrigerator','Infection & testing',['blood bank','laboratory','storage','transfusion'],'Maintains controlled storage conditions for blood components.','Purpose-built refrigerators monitor temperature and may include alarms, logging, and access controls.','Blood-bank staff follow validated storage ranges, alarm response, and local transfusion-service procedures.',['Helmer','Thermo Fisher Scientific','B Medical Systems','Remi'],'Blood bank / laboratory'),
  addDevice('heater-cooler','Cardiopulmonary heater-cooler system','Heart & circulation',['cardiac surgery','temperature management','perfusion','hospital'],'Manages temperature of fluids used in selected cardiopulmonary procedures.','A heater-cooler unit circulates temperature-controlled water through compatible heat exchangers in a clinical setup.','Operated and maintained by trained perfusion or clinical engineering staff under current infection-control guidance.',['Getinge','LivaNova','Maquet','Terumo'],'Cardiac operating room'),
  addDevice('cathlab-system','Cardiac catheterization imaging system','Heart & circulation',['cath lab','angiography','cardiology','x-ray imaging'],'Uses fluoroscopic X-ray imaging to guide catheter-based cardiovascular procedures.','A cath-lab system combines an imaging gantry, detector, table, and image-processing equipment.','Operated by trained interventional teams with radiation-safety protocols.',['Philips','GE HealthCare','Siemens Healthineers','Canon Medical'],'Cath lab / hospital'),
  addDevice('surgical-table','Operating table','Surgery & wound care',['surgery','operating room','patient positioning','hospital'],'Positions and supports a patient during surgery.','Operating tables have adjustable sections and may use specialty tops, attachments, and imaging-compatible designs.','Configured by trained operating-room staff for the procedure and patient, following safe-load and positioning instructions.',['Maquet','STERIS','Stryker','Mindray'],'Operating room'),
  addDevice('c-arm','Mobile C-arm imaging system','Surgery & wound care',['x-ray','fluoroscopy','surgery','imaging'],'Provides real-time X-ray images during selected procedures.','A mobile C-arm positions an X-ray source and detector around the patient to produce fluoroscopic or snapshot images.','Used by trained imaging and clinical teams with radiation protection and model-specific checks.',['GE HealthCare','Siemens Healthineers','Philips','Ziehm Imaging'],'Operating room / imaging center'),
  addDevice('dialyzer','Hemodialyzer (dialysis filter)','Kidney & urinary',['kidney','dialysis','dialyzer','blood filtration'],'Filters waste and excess fluid from blood during hemodialysis.','A dialyzer contains a semipermeable membrane and is matched to a prescribed dialysis setup.','Selected and connected by trained dialysis staff; it is used with a dialysis machine and vascular access plan.',['Fresenius Medical Care','Baxter','Nipro','B. Braun'],'Dialysis center / home program'),
  addDevice('blood-gas-analyzer','Blood-gas analyzer','Infection & testing',['laboratory','blood gas','critical care','diagnosis'],'Measures selected gases and related analytes in a blood sample.','Blood-gas analyzers provide rapid measurements used in acute and laboratory care; test menus vary by model.','Authorized staff collect and run samples under the instrument’s quality-control and sample-handling procedures.',['Radiometer','Siemens Healthineers','Werfen','Roche'],'Hospital / laboratory'),
  addDevice('electrolyte-analyzer','Electrolyte analyzer','Infection & testing',['laboratory','electrolyte','blood test','diagnostic'],'Measures selected electrolytes in blood or other validated sample types.','Electrolyte analyzers use methods such as ion-selective electrodes; test panels and sample requirements vary.','Laboratory staff run samples with model-specific quality controls and review flags before reporting.',['Siemens Healthineers','Roche','Erba Mannheim','Medica Corporation'],'Laboratory'),
  addDevice('patient-monitor','Multiparameter bedside monitor','Heart & circulation',['patient monitor','vital signs','ICU','monitoring'],'Displays selected vital signs such as ECG, oxygen saturation, blood pressure, and temperature.','A bedside monitor combines compatible sensors and modules to show trends and alarms; available parameters vary by configuration.','Clinical staff connect the correct sensors, set patient-specific alarm limits, and interpret readings in context.',['Philips','GE HealthCare','Mindray','Nihon Kohden'],'ICU / hospital'),
  addDevice('orthosis-brace','Orthosis and support brace','Bones, joints & mobility',['orthopedic','brace','orthosis','rehabilitation','mobility'],'Supports or limits movement at a body region as part of an individualized care plan.','Orthoses range from ankle-foot and knee braces to back supports; designs and intended functions are device-specific.','A clinician or orthotist helps select and fit the brace; follow the prescribed wear and skin-check guidance.',['Össur','Ottobock','DJO','Breg'],'Rehabilitation / home'),
  addDevice('exam-couch','Patient examination couch','Hospital & pharmacy',['examination','clinic','patient positioning','hospital'],'Provides a stable surface for clinical examination and selected procedures.','Examination couches may be fixed or height-adjustable and can include backrest and positioning sections.','Staff check stability and safe working load, position the patient, and clean surfaces between uses.',['Midmark','Hillrom','Arjo','Paramount Bed'],'Clinic / hospital')
];
devices.push(...additionalDevices);
// Public manufacturer and healthcare-provider demonstrations for the existing
// device guides. These stay inside section 02 (How it is generally used).
// Links point to the original sources; model-specific manuals remain authoritative.
const howToResources={
  'glucometer':{title:'Contour Plus One: testing walkthrough',kind:'Manufacturer video',url:'https://www.youtube.com/watch?v=dXaB3TLSAdA',note:'Model-specific example; meter and strip procedures vary.',steps:['Wash and dry hands; prepare the matching strip and lancing device.','Obtain a small blood sample using the lancing device instructions.','Apply the sample as the meter manual shows, then record and interpret the result with the care plan.']},
  'cgm':{title:'FreeStyle Libre sensor application and tutorials',kind:'Manufacturer video and tutorial library',url:'https://www.freestyle.abbott/uk-en/support/tutorialsanddownloads.html',note:'Sensor placement, wear time, and replacement are model-specific.',steps:['Choose and prepare the approved application site as the model guide directs.','Apply and activate the sensor using the supplied applicator and compatible reader/app.','Follow the device alerts and replacement schedule; confirm readings when the labeling or care team says to.']},
  'bp-monitor':{title:'OMRON upper-arm monitor: how to measure',kind:'Manufacturer video',url:'https://www.youtube.com/watch?v=lJyNe8WNhBY',note:'Video covers a representative OMRON model; cuff fit and controls vary.',steps:['Rest quietly, seated with back supported and feet flat.','Place the correctly sized cuff on a bare arm, supported at heart level.','Remain still during measurement and record readings as your clinician recommends.']},
  'pulse-ox':{title:'Nonin GO2 fingertip oximeter demonstration',kind:'Manufacturer video',url:'https://www.youtube.com/watch?v=ghUTSH-PYio',note:'Representative home model; use the exact device manual.',steps:['Warm the hand and sit still; remove anything that interferes with the sensor.','Fit the fingertip sensor as shown in the manual.','Wait for a stable display and interpret it with symptoms and professional advice.']},
  'cpap':{title:'AirSense 11 setup and support',kind:'Manufacturer setup guide and videos',url:'https://support.resmed.com/en-in/sleep-devices/airsense-11-autoset',note:'Use prescribed settings only; mask fitting and cleaning instructions vary.',steps:['Assemble the prescribed device, humidifier, tubing, and fitted mask as instructed.','Use the prescribed settings and wear the mask during sleep.','Clean and replace components on the manufacturer schedule; contact the sleep team about problems.']},
  'thermometer':{title:'Braun thermometer: illustrated how-to',kind:'Manufacturer illustrated guide',url:'https://www.braunhealthcare.com/uk_en/how-thermometer/',note:'Ear, forehead, and oral models use different techniques; follow the exact model leaflet.',steps:['Select the measurement site permitted by the model and prepare the thermometer.','Position the sensor as illustrated and take the reading.','Clean the device as directed and note the measurement site when sharing the result.']},
  'stethoscope':{title:'Littmann education: use and care',kind:'Manufacturer education and videos',url:'https://www.littmann.com/en-gb/home/education/',note:'Clinical listening technique is intended for trained users.',steps:['Select the appropriate chestpiece side and ensure the eartips face forward.','Place the chestpiece on the examination site and listen in a quiet setting.','Clean between patients and store the instrument according to its care instructions.']},
  'ecg':{title:'NHS: what happens during an ECG',kind:'Patient step guide',url:'https://www.nhs.uk/tests-and-treatments/electrocardiogram/',note:'Explains a clinical test; electrode placement is performed by staff.',steps:['Staff may ask you to remove upper-body clothing and lie comfortably.','Electrodes are attached to the chest and limbs while the ECG records briefly.','The electrodes are removed; a clinician reviews the trace and explains follow-up.']},
  'holter':{title:'NHS: ambulatory ECG and Holter monitoring',kind:'Patient step guide',url:'https://www.nhs.uk/tests-and-treatments/electrocardiogram/',note:'Wear and water-exposure directions depend on the recorder supplied.',steps:['A clinic fits the recorder and electrodes and explains how to wear them.','Continue agreed daily activities and keep a symptom/activity diary if requested.','Return the recorder as instructed so the care team can analyze the recording.']},
  'pacemaker':{title:'Medtronic MyCareLink monitor setup',kind:'Manufacturer patient setup guide/video',url:'https://www.medtronic.com/en-ca/l/your-health/treatments-therapies/remote-monitoring-heart-devices/mycarelink-monitor/setup-instructions.html',note:'This is for remote follow-up equipment, not implantation or pacemaker programming.',steps:['Use the clinic-issued home monitor and follow its setup instructions.','Complete a transmission when requested by your device clinic.','Contact the clinic for symptoms or device concerns; do not attempt to adjust the implant.']},
  'aed':{title:'American Red Cross: how to use an AED',kind:'Public emergency video and step guide',url:'https://www.redcross.org/take-a-class/aed/using-an-aed',note:'Follow the AED’s prompts and local emergency-service guidance.',steps:['Call emergency services, start CPR, and turn on the AED.','Expose and dry the chest as needed, then attach pads as pictured.','Keep everyone clear during analysis/shock and follow prompts; resume CPR when directed.']},
  'insulin-pump':{title:'MiniMed 780G training resources',kind:'Manufacturer training and manuals',url:'https://origin.medtronicdiabetes.com/minimed-780g-training-resources',note:'Clinical training is required. Do not copy insulin settings or dosing from a general guide.',steps:['Complete model-specific training with the diabetes care team before use.','Use only prescribed settings and the compatible infusion components.','Follow the clinician-provided alarm, site-change, and backup plan.']},
  'inhaler-spacer':{title:'Metered-dose inhaler with spacer: technique guide',kind:'Patient video and step guide',url:'https://www.lung.org/lung-health-diseases/lung-disease-lookup/asthma/treatment/devices/metered-dose-inhaler-chamber-spacer-mask',note:'Technique varies by inhaler and chamber; ask a clinician to check your technique.',steps:['Prepare/shake the inhaler if its leaflet says to, then attach it to the chamber.','Seal lips around the mouthpiece or fit the mask; release one puff into the chamber.','Breathe in as taught, wait between prescribed puffs, then clean the chamber as directed.']},
  'nebulizer':{title:'OMRON nebulizer: use and cleaning videos',kind:'Manufacturer video library (Japanese)',url:'https://www.healthcare.omron.co.jp/product/ne/howto/',note:'The located manufacturer video library is Japanese-language; exact assembly differs by model.',steps:['Assemble the prescribed nebulizer kit and add only the medicine and dose prescribed.','Sit upright and breathe through the mouthpiece or mask as directed until treatment ends.','Disassemble and clean/dry components according to the exact manual.']},
  'hearing-aid':{title:'Phonak how-to videos',kind:'Manufacturer video library',url:'https://www.phonak.com/en-in/support/how-to-videos',note:'Controls and fitting steps differ by hearing-aid model and programming.',steps:['Insert or position the hearing aid as demonstrated for its style.','Use the approved controls/app and charging or battery method.','Clean and store it as directed; have fitting or sound issues checked by an audiologist.']},
  'wheelchair':{title:'Berkshire Healthcare: using a wheelchair',kind:'Healthcare-provider video and guide',url:'https://www.berkshirehealthcare.nhs.uk/advice/using-a-wheelchair',note:'Transfer and propulsion training should match the person’s chair and abilities.',steps:['Check the chair, brakes, footplates, and seating before moving.','Use the transfer and propulsion method taught by a rehabilitation professional.','Use ramps and obstacles only as trained; inspect and maintain the chair regularly.']},
  'prosthesis':{title:'Ottobock: prosthetic rehabilitation and gait training',kind:'Manufacturer patient guide and video',url:'https://www.ottobock.com/en-gb/prosthetics/back-to-mobility/gait-training',note:'Donning and walking are individualized and should be taught by the prosthetic rehabilitation team.',steps:['Check skin and limb condition, then don the prosthesis using the taught method.','Begin wear and walking practice according to the individualized therapy plan.','Remove and inspect the skin as instructed; report pain, wounds, or fit changes.']},
  'knee-implant':{title:'NHS: how knee replacement surgery is done',kind:'Patient procedure guide and video',url:'https://www.nhs.uk/tests-and-treatments/knee-replacement/how-its-done/',note:'This describes surgery and recovery; the implant is not a patient-operated product.',steps:['Before surgery, the team reviews health, anesthesia, and preparation.','The surgeon replaces the damaged joint surfaces during the operation.','Recovery and rehabilitation follow the individualized hospital plan.']},
  'dialysis':{title:'National Kidney Foundation: hemodialysis education',kind:'Patient guide and videos',url:'https://www.kidney.org/kidney-topics/hemodialysis',note:'Home hemodialysis requires a prescribed program and extensive formal training.',steps:['The renal team checks access and prepares the prescribed treatment setup.','Treatment runs through the dialyzer with trained monitoring.','After treatment, follow access-care and symptom-reporting instructions.']},
  'urinary-catheter':{title:'Intermittent catheterization: patient demonstration',kind:'Patient video and product guide',url:'https://www.youtube.com/watch?v=Eg99g_-9AYE',note:'The located video is one technique example. Catheter type, anatomy, and clinician instructions matter; request hands-on training.',steps:['Wash hands and prepare the prescribed catheter and clean supplies.','Use the insertion method taught by a clinician for your catheter and situation.','Drain urine as instructed, dispose/store the catheter as labeled, and follow infection-prevention advice.']},
  'endoscope':{title:'Olympus endoscope reprocessing training',kind:'Manufacturer professional training videos',url:'https://infectionprevention.olympus.com/en-us/scientific-evidence/trainings/',note:'Professional-only reprocessing content; endoscopy itself is performed by trained clinical staff.',steps:['Prepare and inspect the scope using the facility’s validated procedure.','Perform cleaning, leak testing, and reprocessing using the exact model instructions.','Document completion and store the scope according to institutional policy.']},
  'syringe':{title:'WHO safe injection guide',kind:'Healthcare-provider illustrated guide',url:'https://cdn.who.int/media/docs/default-source/integrated-health-services-%28ihs%29/injection-safety/is_providers-guide.pdf',note:'A syringe is not a standalone treatment. Use only after appropriate clinical instruction and for its labeled purpose.',steps:['Confirm the medicine, route, syringe type, and dose against the prescription and training.','Prepare and administer using the approved aseptic technique for that route.','Dispose of the needle immediately in an approved sharps container.']},
  'iv-pump':{title:'Baxter product training for infusion pumps',kind:'Manufacturer professional training',url:'https://support.baxter.com/en/training/us-self-service-product-training/',note:'For trained healthcare professionals; patient users should not program pump settings.',steps:['Verify the pump, line, medication, and order using local clinical checks.','Prime and program only as trained, following the exact pump instructions and safety checks.','Monitor the infusion and alarms; escalate problems per facility protocol.']},
  'xray':{title:'RadiologyInfo: X-ray examination',kind:'Radiology patient guide',url:'https://www.radiologyinfo.org/en/info/x-ray',note:'Patient preparation and views vary by body part and facility.',steps:['Follow preparation instructions and tell staff about relevant conditions or pregnancy possibility.','Position as directed and remain still while the radiographer takes the images.','Resume normal activity unless the care team gives other instructions; ask how results will be shared.']},
  'ultrasound':{title:'GE Venue ultrasound: getting started',kind:'Manufacturer operator video',url:'https://www.youtube.com/watch?v=ActEABRpBr0',note:'This is clinician/operator training, not patient instructions; probes and controls vary.',steps:['Select the appropriate probe and exam preset for the clinical task.','Apply gel and scan using the trained technique and infection-control guidance.','Save measurements/images and clean the probe according to its instructions.']},
  'mri':{title:'RadiologyInfo: preparing for an MRI exam',kind:'Radiology patient guide',url:'https://www.radiologyinfo.org/en/info/how-to-prepare-for-mri-exam',note:'MRI safety screening is essential; follow the facility’s implant and metal screening process.',steps:['Complete safety screening and remove items prohibited in the scanner room.','Change or prepare as directed, then lie still while the technologist positions you.','Follow breathing or contrast instructions and ask the facility when results will be available.']},
  'neurostim':{title:'Medtronic: living with deep brain stimulation',kind:'Manufacturer patient guide',url:'https://www.medtronic.com/in-en/patients/treatments-therapies/deep-brain-stimulation-parkinsons-disease/living-with-dbs/your-involvement-in-the-therapy.html',note:'Implantation and programming are specialist tasks; follow your own clinic’s device plan.',steps:['Attend specialist assessment, surgery, and programming visits as scheduled.','Use any patient controller only as the device team has taught you.','Keep follow-up appointments and report symptom or device changes to the clinic.']},
  'wound-dressing':{title:'Mepilex Border: application guide',kind:'Manufacturer illustrated guide',url:'https://corporate.molnlycke.com/SysSiteAssets/master-and-local-markets/documents/master/wound-care-documents/patient-guides/mepilex-border-user-application-guide.pdf',note:'Specific to one dressing; dressing choice and change timing should be clinician-directed.',steps:['Clean and dry the surrounding skin as advised by the wound-care team.','Apply the dressing with the wound centered, following the product guide.','Change it at the prescribed interval or if saturated/loose; seek advice for worsening signs.']},
  'pregnancy-test':{title:'Clearblue: how to use a pregnancy test',kind:'Manufacturer illustrated guide and videos',url:'https://uk.clearblue.com/pregnancy-tests/how-to-use',note:'Read the leaflet for the exact test and read results only within its stated time window.',steps:['Check the test leaflet, expiry date, and recommended testing time.','Collect or expose the urine sample exactly as the product instructions state.','Wait the stated time and interpret the display using that test’s leaflet.']},
  'ivd-analyzer':{title:'Roche cobas pro operator documentation',kind:'Manufacturer operator manual',url:'https://elabdoc-prod.roche.com/eLD/api/downloads/8264dd59-0be3-ec11-1491-005056a772fd?countryIsoCode=IN',note:'Laboratory-professional equipment; no patient operation. Training and local quality procedures are required.',steps:['Complete authorized operator training and verify the correct instrument configuration.','Load samples/reagents and run assays according to the model instructions and lab SOP.','Review quality-control status, flags, and results under laboratory procedures.']},
  'colonoscope':{title:'NHS: what happens during a colonoscopy',kind:'Patient procedure guide and video',url:'https://www.nhs.uk/tests-and-treatments/colonoscopy/',note:'Patient preparation and the examination are managed by the endoscopy team.',steps:['Follow bowel-preparation and medication instructions supplied by the clinic.','During the procedure, the clinician passes the camera and may take samples or treat findings.','Follow recovery, transport, and result instructions from the endoscopy team.']},
  'hemodialysis-access':{title:'National Kidney Foundation: hemodialysis access care',kind:'Patient step guide',url:'https://www.kidney.org/hemodialysis-access',note:'Access checks and care should follow the renal team’s instructions.',steps:['Learn the access type and daily checks taught by the dialysis team.','Keep the site clean and protect it from pressure or injury as instructed.','Report redness, swelling, pain, bleeding, fever, or a change in the access promptly.']},
  'surgical-robot':{title:'Intuitive: how the da Vinci system works',kind:'Manufacturer explainer video',url:'https://www.intuitive.com/en-us/patients/da-vinci-robotic-surgery/about-the-systems',note:'The system is controlled by a trained surgeon; this is an overview, not patient operating instructions.',steps:['The surgeon and operating team prepare the system and instruments for the procedure.','The surgeon controls the instruments from a console while viewing the surgical field.','The clinical team completes the operation and post-operative care plan.']},
  'mammography':{title:'RadiologyInfo: mammography examination',kind:'Radiology patient guide',url:'https://www.radiologyinfo.org/en/info/mammo',note:'Positioning and views are performed by trained mammography staff.',steps:['Tell staff about symptoms, prior images, implants, or relevant history.','The technologist positions and briefly compresses each breast for the required views.','Ask how and when results will be communicated; follow any recall instructions.']},
  'bone-densitometer':{title:'NHS: what happens during a DXA scan',kind:'Patient step guide',url:'https://www.nhs.uk/tests-and-treatments/dexa-scan/',note:'A trained operator positions the patient and a clinician interprets the result.',steps:['Follow the appointment instructions and tell staff about relevant medicines or recent contrast tests.','Lie on the scan table while the scanner measures the requested sites.','The scan is reviewed and results are explained by the referring care team.']},
  'nebulizer-spacer':{title:'NHS: peak flow test technique',kind:'Patient step guide',url:'https://www.nhs.uk/tests-and-treatments/peak-flow-test/',note:'Use the technique and recording schedule in your personal asthma action plan.',steps:['Reset the meter and stand or sit upright as instructed.','Take a deep breath, seal lips around the mouthpiece, then blow out hard and fast.','Repeat as directed, record the best reading, and follow your action plan.']},
  'neuro-wheel':{title:'Cochlear Nucleus 8: device basics and support',kind:'Manufacturer user videos and guide',url:'https://www.cochlear.com/us/en/home/ongoing-care-and-support/device-help-and-support/device-basics/cochlear-nucleus-portfolio/nucleus-8',note:'External processor instructions are model-specific; implant surgery and mapping are specialist tasks.',steps:['Attach and position the external sound processor as your audiologist demonstrated.','Power/connect it using the approved battery or accessory instructions.','Clean, charge, and troubleshoot using the model guide; attend mapping and rehabilitation visits.']}
};
