devices.forEach(device=>{
  if(indiaDeviceCatalog[device.id]) return;
  const models=comparisonProfiles[device.id]||[];
  const features=comparisonFeatures[device.id]||[device.short,device.what,device.use];
  indiaDeviceCatalog[device.id]=device.brands.map((brand,index)=>{
    const model=models[index]||`${brand} ${device.name} product range`;
    const search=encodeURIComponent(`${brand} ${model} official product`);
    const image=devicePhotos[device.id]?.src||'';
    const isAccess= device.id==='hemodialysis-access';
    return {id:`${device.id}-${index}`,brand,name:model,price:isAccess?'Procedure / quote-based':'Request quote',mrp:'No public India list price found',availability:isAccess?'Clinically planned; not a retail listing':'Model availability varies by country',package:isAccess?'Access route and materials selected by renal/vascular team':'Configuration, accessories and service package vary by model',features:[...features],differentiator:features[index%features.length],image,imageSource:devicePhotos[device.id]?.source||'https://www.google.com/search?q='+search,seller:'Manufacturer information',listing:'https://www.google.com/search?q='+search,priceNote:isAccess?'This is a clinical access option, not a standalone branded device price.':'India price requires an authorized dealer quote; no comparable public model price was located.'};
  });
});
const addVerified= (deviceId,index,details)=>Object.assign(indiaDeviceCatalog[deviceId][index],details);
